package dev.gustavopere.rpgskilltree.core;
import java.util.*;
public final class ArchetypeResolver{private ArchetypeResolver(){}private static final Comparator<ArchetypeMatch> ORDER=Comparator.comparingInt(ArchetypeMatch::priority).reversed().thenComparing(Comparator.comparingInt(ArchetypeMatch::specificity).reversed()).thenComparing(Comparator.comparingInt(ArchetypeMatch::matchedScore).reversed()).thenComparing(ArchetypeMatch::archetypeId);public static List<ArchetypeMatch> resolve(InvestmentState s,Collection<ArchetypeDefinition>d){return d.stream().filter(x->match(s,x)).map(x->new ArchetypeMatch(x.id(),x.priority(),x.specificity(),x.minimumDomainScores().keySet().stream().mapToInt(s::domainScore).sum())).sorted(ORDER).toList();}private static boolean match(InvestmentState s,ArchetypeDefinition d){return d.minimumDomainScores().entrySet().stream().allMatch(e->s.domainScore(e.getKey())>=e.getValue())&&d.requiredTags().stream().allMatch(s::hasTag)&&d.forbiddenTags().stream().noneMatch(s::hasTag);}}
